"""Targeted: stale heap entries + id reuse + idle expiry, vs reference."""
import json, os, random, subprocess, sys, tempfile
sys.path.insert(0,'.')
import ref, diff, gen

def canon(v): return json.dumps(v, separators=(",",":"), ensure_ascii=True).encode()

def make_workload(seed, nit=1, nflows=2, nsteps=400):
    rng = random.Random(seed)
    reqs=[]; t=0; live=set()
    for _ in range(nsteps):
        r=rng.random()
        if r<0.3 or not live:
            cand=[i for i in range(nflows) if i not in live]
            if cand:
                f=rng.choice(cand)
                if rng.random()<0.4: t+=1
                reqs.append({"op":"open","flow":f,"time":t}); live.add(f)
        elif r<0.45:
            f=rng.choice(sorted(live))
            if rng.random()<0.4: t+=rng.randrange(1,3)
            reqs.append({"op":"close","flow":f,"time":t}); live.discard(f)
        elif r<0.55:
            t+=rng.randrange(1,3)
            reqs.append({"op":"tick","time":t})
        else:
            pk=[]
            for _ in range(rng.randrange(1,5)):
                if not live: break
                f=rng.choice(sorted(live))
                if rng.random()<0.5: t+=1
                pk.append({"flow":f,"time":t,"source":rng.randrange(2),"length":rng.choice([1,2,3,7])})
            if pk: reqs.append({"op":"chunk","packets":pk})
    for f in sorted(live):
        t+=1; reqs.append({"op":"close","flow":f,"time":t})
    return [(r, False) for r in reqs]

bad=0
for seed in range(150):
    rng=random.Random(1000+seed)
    cfg={"version":1,"idle_timeout":rng.choice([0,1,1,2,3]),"packet_limit":rng.choice([1,3,100]),
         "prefix_width":rng.choice([1,2,4]),
         "rules":[{"id":i,"class":i,"priority":rng.randrange(-2,3),"ranges":[[1,1],[2,3],[1,1]]} for i in rng.sample(range(20),rng.randrange(0,5))],
         "fallback":{"feature":0,"threshold":1,"le":{"class":8},"gt":{"class":9}}}
    reqs=make_workload(seed, nflows=rng.randrange(1,4))
    try:
        diff.run_case(cfg, reqs, seed, restart_p=0.5)
    except AssertionError as e:
        bad+=1
        print("seed",seed,"FAILED",e)
        print(json.dumps(cfg))
        for r,_ in reqs[:40]: print("  ",canon(r).decode())
        break
print("done, failures:",bad)
